def longest_increasing_subsequence(nums):
    n = len(nums)
    length = [1] * n
    parent = list(range(n))
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and length[j] + 1 > length[i]:
                length[i] = length[j] + 1
                parent[i] = j
    end = max(range(n), key=lambda index: (length[index], -index))
    sequence = [nums[end]]
    while parent[end] != end:
        end = parent[end]
        sequence.append(nums[end])
    return sequence[::-1]

