def min_cost_cuts(n, cuts):
    points = [0] + sorted(cuts) + [n]
    m = len(points)
    cost = [[0] * m for _ in range(m)]
    for gap in range(2, m):
        for i in range(m - gap):
            j = i + gap
            cost[i][j] = points[j] - points[i] + min(cost[i][k] + cost[k][j] for k in range(i + 1, j))
    return cost[0][m - 1]

