def max_coins(nums):
    values = [1] + nums + [1]
    n = len(values)
    best = [[0] * n for _ in range(n)]
    for gap in range(2, n):
        for left in range(n - gap):
            right = left + gap
            best[left][right] = max(
                best[left][k] + best[k][right] + values[left] * values[k] * values[right] for k in range(left + 1, right)
            )
    return best[0][n - 1]

